function finalText(log) {
  const typed = [];
  for (const ch of log) {
    if (ch === '#') {
      if (typed.length > 0) typed.pop();
    } else {
      typed.push(ch);
    }
  }
  return typed.join('');
}

function sameFinalText(logA, logB) {
  return finalText(logA) === finalText(logB);
}

tests.code:
assertEqual(sameFinalText('xy#z', 'xzz#'), true);
assertEqual(sameFinalText('bxj##tw', 'bxo#j##tw'), true);
assertEqual(sameFinalText('bxj##tw', 'bxj###tw'), false);
